THEME = ("T02", "Contrôle d'accès discrétionnaire (DAC)")
SOURCE = "TCSEC « Orange Book » DoD 5200.28-STD (1985) ; Lampson, « Protection », 1971 ; Harrison, Ruzzo, Ullman, 1976 ⚠ à vérifier"
Q = [
(1,"Dans un modèle DAC, qui décide en principe des droits sur un fichier ?","Son propriétaire","Un comité de sécurité central","L'ordinateur seul, sans personne","Le fournisseur d'accès",
 "« Discrétionnaire » signifie que le propriétaire accorde ou retire les droits à sa discrétion."),
(1,"Quel système d'exploitation courant repose sur le DAC pour ses fichiers ?","Linux avec les permissions rwx","Un système à étiquettes de sécurité multi-niveaux","Un pare-feu applicatif","Un module de chiffrement matériel",
 "Les permissions Unix (propriétaire, groupe, autres) sont un DAC classique."),
(1,"Que peut faire le propriétaire d'un fichier en DAC ?","Accorder des droits à d'autres utilisateurs","Modifier les niveaux de classification de l'entreprise","Changer la politique de sécurité globale","Retirer les droits de l'administrateur système",
 "Le pouvoir de partager est la caractéristique du DAC."),
(1,"Quel est le principal avantage du DAC ?","La souplesse du partage entre utilisateurs","La garantie d'une politique unique pour toute l'entreprise","L'impossibilité de fuite","L'absence de gestion",
 "Chacun partage simplement ce qu'il possède, sans passer par un administrateur."),
(2,"Quel est le principal inconvénient du DAC ?","Un propriétaire peut transmettre ses droits à qui il veut, hors de tout contrôle central","Il est impossible de lire un fichier","Il impose un seul propriétaire par entreprise","Il interdit le partage de dossiers",
 "La politique dépend des choix individuels : une fuite volontaire ou par erreur n'est pas bloquée."),
(2,"Qu'est-ce qu'un « cheval de Troie » face à un DAC ?","Un programme qui agit avec les droits de l'utilisateur qui l'exécute pour copier ses données","Un mot de passe trop simple","Une sauvegarde chiffrée","Un pare-feu mal réglé",
 "Le programme hérite des droits de l'utilisateur ; le DAC ne distingue pas l'intention de l'utilisateur de celle du programme."),
(2,"Pourquoi un DAC ne protège-t-il pas contre la copie d'une donnée par un utilisateur autorisé ?","Une fois la lecture permise, rien ne contrôle où il la recopie","Parce qu'il chiffre tout","Parce qu'il refuse les copies de petite taille","Parce qu'il supprime les journaux",
 "Le DAC contrôle l'accès à l'objet, pas la circulation de l'information ensuite."),
(1,"Que signifie rwx sur un fichier Unix ?","Lecture, écriture, exécution","Redémarrage, sauvegarde, export","Rapide, web, extensible","Racine, groupe, autres",
 "r pour read, w pour write, x pour execute."),
(1,"Dans « rw-r-----  », que peut faire le groupe ?","Lire","Lire et écrire","Exécuter","Rien",
 "Les trois premiers caractères concernent le propriétaire, les trois suivants le groupe : ici r--."),
(1,"Dans « rw-r-----  », que peuvent faire les autres utilisateurs ?","Rien","Lire","Écrire","Exécuter",
 "Les trois derniers caractères sont « --- » : aucun droit."),
(2,"Que vaut la permission rwxr-x--- en notation octale ?","750","755","640","700",
 "rwx = 7, r-x = 5, --- = 0 : 750."),
(2,"Que vaut la permission 644 en notation symbolique ?","rw-r--r--","rwxr--r--","rw-rw-r--","rw-r-----",
 "6 = rw-, 4 = r--, 4 = r-- : rw-r--r--."),
(2,"Quelle commande modifie les permissions d'un fichier sous Linux ?","chmod","chown","passwd","ls",
 "chmod change les permissions ; chown change le propriétaire ou le groupe."),
(2,"Quelle commande change le propriétaire d'un fichier sous Linux ?","chown","chmod","umask","su",
 "chown (change owner) attribue un autre propriétaire ou groupe."),
(2,"Qu'est-ce que le umask sous Unix ?","Un masque qui retire des droits aux fichiers nouvellement créés","Une commande de sauvegarde","Un type de groupe","Un journal d'accès",
 "Avec un umask 022, un nouveau fichier reçoit 644 au lieu de 666."),
(3,"Avec un umask 027, quelles permissions reçoit un nouveau fichier créé avec un mode de départ 666 ?","640","644","600","660",
 "666 moins les bits du masque 027 (groupe : w retiré, autres : rwx retirés) donne rw-r-----, soit 640."),
(2,"Que permet le droit x sur un répertoire Unix ?","Y entrer et accéder à son contenu par nom","L'exécuter comme programme","Le supprimer","Le copier",
 "Sans x sur un répertoire, on ne peut pas y accéder même si on connaît le nom d'un fichier."),
(3,"Quel droit faut-il sur un répertoire pour y supprimer un fichier appartenant à un autre ?","w sur le répertoire (et x), sauf sticky bit","w sur le fichier","r sur le répertoire","Aucun droit particulier",
 "La suppression modifie le répertoire ; le sticky bit restreint cela au propriétaire du fichier."),
(3,"À quoi sert le sticky bit sur /tmp ?","Seul le propriétaire d'un fichier peut le supprimer ou le renommer","Il chiffre les fichiers","Il rend les fichiers en lecture seule","Il donne les droits root",
 "Sans lui, tout utilisateur ayant w sur /tmp pourrait supprimer les fichiers des autres."),
(3,"Que fait le bit setuid sur un exécutable Unix ?","Il s'exécute avec les droits de son propriétaire","Il interdit son exécution","Il le rend invisible","Il l'exécute avec les droits du groupe de l'appelant",
 "Utile pour passwd, mais dangereux si le programme est vulnérable : risque d'élévation de privilèges."),
(2,"Pourquoi les programmes setuid root sont-ils surveillés par les équipes de sécurité ?","Une faille dans l'un d'eux donne des droits administrateur","Ils consomment beaucoup de mémoire","Ils sont toujours chiffrés","Ils ne peuvent pas être journalisés",
 "Leur surface d'attaque est critique : on en minimise le nombre."),
(2,"Qu'apportent les ACL POSIX par rapport aux permissions Unix classiques ?","Des droits pour des utilisateurs ou groupes supplémentaires précis","L'abandon du propriétaire","Un chiffrement des fichiers","La suppression du groupe",
 "Les ACL permettent plusieurs entrées nommées au-delà du trio propriétaire, groupe, autres."),
(2,"Quelle commande affiche les ACL POSIX d'un fichier sous Linux ?","getfacl","getent","getpass","ls -t",
 "getfacl lit les ACL ; setfacl les modifie."),
(2,"Comment Windows NTFS stocke-t-il les droits d'un fichier ?","Dans une ACL composée d'entrées de contrôle d'accès (ACE)","Dans trois bits rwx","Dans un fichier texte partagé","Dans le registre du navigateur",
 "Chaque ACE associe un utilisateur ou groupe à des droits autorisés ou refusés."),
(3,"Dans les ACL NTFS, que se passe-t-il en cas de conflit entre un refus explicite et une autorisation ?","Le refus explicite l'emporte généralement","L'autorisation l'emporte toujours","Le droit le plus ancien l'emporte","Le conflit bloque le système",
 "Un « Refuser » explicite est prioritaire sur « Autoriser » dans l'évaluation standard."),
(2,"Qu'est-ce que l'héritage des permissions sur un dossier ?","Les éléments créés dedans reçoivent les permissions du parent","Le fichier copie les droits d'un autre propriétaire","Les droits sont transmis au système de fichiers entier","L'administrateur reçoit tous les droits",
 "L'héritage simplifie l'administration mais peut propager une erreur sur toute une arborescence."),
(3,"Quel risque l'héritage des permissions peut-il causer ?","Une erreur au sommet se propage à tout le sous-arbre","Il supprime les journaux","Il empêche le partage","Il verrouille tous les comptes",
 "Un droit trop large accordé sur un dossier parent s'applique à tout ce qu'il contient."),
(2,"Qu'est-ce que le « partage Everyone » en contrôle d'accès ?","Un droit accordé à tous les utilisateurs authentifiés ou non selon la configuration","Un partage réservé aux administrateurs","Un droit accordé au seul propriétaire","Un droit supprimé par défaut sur les fichiers système",
 "Un « Tout le monde » en écriture sur un partage de fichiers est une erreur classique de configuration."),
(2,"Pourquoi faut-il éviter d'attribuer des droits directement à des utilisateurs plutôt qu'à des groupes ?","La gestion devient lourde et sujette aux oublis","Les utilisateurs ne peuvent pas se connecter","Les groupes sont chiffrés","Windows l'interdit",
 "Passer par des groupes permet de modifier les droits d'un ensemble de personnes en une seule opération."),
(3,"Le modèle de matrice d'accès de Harrison, Ruzzo et Ullman (HRU) a montré que :","Déterminer si un droit peut fuiter est indécidable dans le cas général","Tous les droits peuvent être calculés en temps constant","Le DAC est toujours sûr","La matrice ne peut contenir que des 0 et des 1",
 "Ce résultat de 1976 explique pourquoi on cherche des modèles plus contraints que le DAC pur."),
(2,"Quelle conséquence a la possibilité de « re-délégation » des droits en DAC ?","Le propriétaire initial perd le contrôle de la diffusion","Les droits disparaissent","L'administrateur est averti automatiquement","Le fichier est chiffré",
 "Un bénéficiaire peut lui-même partager : la chaîne de confiance échappe à celui qui a créé l'objet."),
(1,"Que signifie « propriétaire » d'un fichier ?","L'utilisateur auquel le système attribue le contrôle de ses droits","Celui qui l'a imprimé","Le dernier utilisateur connecté","L'administrateur réseau",
 "Le propriétaire est généralement celui qui a créé l'objet."),
(2,"Qu'arrive-t-il aux fichiers d'un salarié parti si ses droits sont purement discrétionnaires ?","Ils restent sans propriétaire actif, d'où un besoin de reprise en main","Ils sont supprimés automatiquement","Ils deviennent publics","Ils sont chiffrés",
 "Le départ d'un propriétaire pose le problème des objets orphelins : il faut une procédure de transfert."),
(2,"Quel point de contrôle central un administrateur peut-il garder dans un DAC ?","Le droit de changer le propriétaire ou de reprendre la main","Aucun","La modification des mots de passe des autres uniquement","Le blocage des journaux",
 "Dans les systèmes courants, un administrateur (root) peut contourner la décision du propriétaire."),
(2,"Quel est l'effet d'un répertoire partagé en écriture pour tout le monde dans un DAC ?","Chacun peut modifier ou supprimer ce que d'autres ont déposé","Les fichiers deviennent immuables","Seul le propriétaire peut lire","Les droits sont refusés à tous",
 "Sans sticky bit ni ACL, l'écriture ouverte à tous met en péril l'intégrité."),
(1,"Quelle information le champ « groupe » d'un fichier Unix indique-t-il ?","Le groupe d'utilisateurs auquel s'appliquent les permissions intermédiaires","Le serveur de sauvegarde","La taille maximale","Le type de chiffrement",
 "Les droits du groupe se situent entre ceux du propriétaire et ceux des autres."),
(2,"Quel est le droit effectif d'un utilisateur dont un groupe donne r-- et dont un autre groupe donne rw- (cumul de groupes) ?","Il peut lire et écrire (cumul des droits)","Il ne peut que lire","Il ne peut rien faire","Il peut seulement exécuter",
 "Sur un système sans refus explicite, les droits des différents groupes s'additionnent."),
(3,"Pourquoi les ACL augmentent-elles le risque d'erreur par rapport aux permissions rwx simples ?","Elles multiplient les entrées, rendant le droit effectif difficile à relire","Elles suppriment le propriétaire","Elles ne peuvent pas être auditées","Elles exigent un redémarrage",
 "Plus il y a d'entrées nominatives, plus la lecture et la revue des droits sont complexes."),
(2,"Quel outil permet de vérifier les droits effectifs d'un utilisateur sur un fichier ?","L'onglet « Accès effectif » ou une commande équivalente","L'éditeur de texte","Le gestionnaire de mots de passe","L'outil de sauvegarde",
 "Il combine propriétaire, groupes et ACL pour montrer ce que l'utilisateur peut réellement faire."),
(2,"Quel principe aide à limiter les risques d'un DAC mal maîtrisé ?","Le moindre privilège et la revue régulière des droits","L'augmentation des droits par défaut","La suppression du propriétaire","L'absence de journaux",
 "Réduire les droits au nécessaire limite l'impact des mauvais choix individuels."),
(1,"Comment appelle-t-on un partage où chaque utilisateur décide lui-même de qui voit ses documents ?","Un partage discrétionnaire","Un partage obligatoire","Un partage cryptographique","Un partage anonyme",
 "Le choix revient à l'utilisateur : c'est la définition du DAC."),
(2,"Qu'est-ce que le « droit de partager » (grant option) ?","La possibilité pour un bénéficiaire de transmettre à son tour le droit reçu","Le droit de lire seulement","Le droit de supprimer les journaux","Le droit de redémarrer",
 "En SQL, GRANT ... WITH GRANT OPTION illustre cette délégation."),
(2,"En SQL, quelle instruction retire un droit précédemment accordé ?","REVOKE","DROP","DELETE","ALTER",
 "GRANT accorde, REVOKE retire ; DROP supprime un objet."),
(3,"En SQL, que provoque REVOKE ... CASCADE sur un droit déjà re-délégué ?","Il retire aussi les droits transmis à partir de celui-ci","Il supprime la base","Il bloque les connexions","Il change le propriétaire",
 "La cascade traite la chaîne de délégation : les droits re-délégués disparaissent avec leur source."),
(2,"Pourquoi le DAC convient-il mal aux données soumises à une réglementation stricte ?","La conformité exige une politique imposée et démontrable, pas des choix individuels","Parce qu'il est interdit par la loi","Parce qu'il est trop lent","Parce qu'il ne supporte pas les groupes",
 "Un auditeur doit pouvoir démontrer des règles uniformes, ce que le DAC garantit mal."),
(2,"Dans le DAC, que se passe-t-il quand un utilisateur change le groupe d'un fichier sensible par erreur ?","Un groupe non prévu peut accéder aux données","Rien, le système refuse","Le fichier est chiffré","Le propriétaire perd son compte",
 "Une action individuelle suffit à modifier l'exposition de la donnée, sans validation."),
(1,"Quelle caractéristique distingue le DAC du MAC ?","Le propriétaire peut modifier les droits en DAC, pas en MAC","Le DAC utilise des étiquettes de sécurité, pas le MAC","Le MAC est toujours plus lent","Le DAC interdit les groupes",
 "Dans le MAC, la politique est imposée par le système."),
(3,"Quelle approche peut compléter un DAC pour empêcher une fuite par re-partage ?","Un contrôle obligatoire par étiquettes ou une prévention de fuite de données","Un partage plus ouvert","La suppression des journaux","Un mot de passe commun",
 "Superposer une politique imposée limite ce que les propriétaires peuvent décider."),
(2,"Quel est le droit minimal à donner à un collègue qui doit seulement consulter un dossier ?","Lecture seule","Lecture et écriture","Contrôle total","Propriété",
 "Le moindre privilège suggère r sur les fichiers (et x sur les répertoires)."),
(3,"Un utilisateur a r-x sur un répertoire mais pas de droit sur un fichier qu'il contient. Peut-il lire le fichier ?","Non, le droit sur le fichier est aussi nécessaire","Oui, le droit du répertoire suffit","Oui, mais seulement le nom","Non, car le répertoire est caché",
 "Le chemin doit être traversable (x) et le fichier lui-même doit autoriser la lecture."),
(2,"Qu'est-ce qu'un fichier sans propriétaire valide (« orphelin ») pose comme problème ?","Personne n'a clairement la responsabilité de ses droits","Il ne peut pas être lu","Il est chiffré","Il est supprimé immédiatement",
 "Les orphelins échappent aux revues et peuvent conserver des droits obsolètes."),
(2,"Quelle mesure traite le plus efficacement l'accumulation de droits discrétionnaires dans un grand partage ?","Une revue des droits par les responsables de données","Une augmentation de la taille du disque","Le partage d'un compte","La suppression du journal",
 "Faire valider périodiquement les accès par ceux qui connaissent le besoin remet la politique au centre."),
]
